<?php
declare(strict_types=1);
function landscapeValidate(array $c):array {
    $out=['organization'=>studioText($c['organization']??'',180),'systems'=>[],'stores'=>[],'flows'=>[]];$ids=[];$stores=[];
    $fields=['description'=>2000,'owner'=>180,'realm'=>180,'admins'=>500,'emergencyContact'=>500,'lastUpdate'=>10,'version'=>180,'vendor'=>180,'location'=>500,'platforms'=>1000,'serverType'=>500,'os'=>180,'database'=>500,'apis'=>1500,'backup'=>1500,'processes'=>1500,'functions'=>1500,'kpis'=>1000,'risks'=>1500,'targetGroups'=>1000,'advantages'=>1000,'securityRequirements'=>1500,'compliance'=>1500,'supportContracts'=>1500,'licenses'=>1000,'editorialResponsibility'=>1000,'dataQuality'=>1500,'acquisitionCost'=>500,'maintenanceCost'=>500,'operatingCost'=>500,'amortization'=>500,'migrationCost'=>500,'trainingCost'=>500,'departments'=>1000,'roles'=>1000,'permissions'=>1500,'permissionOwner'=>500,'activity'=>1500];
    foreach(labList($c['systems']??[],labLimits()['nodes']) as $raw){$s=studioRecord($raw);$id=labName($s['id']??null);if(isset($ids[$id]))fail(422,'System-IDs müssen eindeutig sein.');$ids[$id]=true;$v=['id'=>$id,'name'=>labName($s['name']??null,180),'type'=>studioEnum($s['type']??'application',['application','database','platform','service','files','external','other']),'status'=>studioEnum($s['status']??'unknown',['active','planned','retiring','unknown']),'deployment'=>studioEnum($s['deployment']??'unknown',['unknown','on_premises','cloud','hybrid','hosted'])];foreach($fields as $key=>$max)$v[$key]=studioText($s[$key]??'',$max);
        if(array_key_exists('mapPosition',$s)){$position=studioRecord($s['mapPosition']);if(array_diff(array_keys($position),['x','y']))fail(422,'Ungültige Kartenposition.');foreach(['x','y'] as $axis){$n=$position[$axis]??null;if((!is_int($n)&&!is_float($n))||!is_finite((float)$n)||abs($n)>100000)fail(422,'Kartenpositionen müssen endliche Zahlen zwischen −100000 und 100000 sein.');}$v['mapPosition']=['x'=>$position['x'],'y'=>$position['y']];}
        $regulatory=studioRecord($s['regulatory']??[]);$v['regulatory']=[];foreach(['ai_act','dsa','dma','gdpr'] as $rule)$v['regulatory'][$rule]=studioEnum($regulatory[$rule]??'not_assessed',['not_assessed','relevant','not_relevant']);
        if($v['lastUpdate']!==''&&(!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D',$v['lastUpdate'],$date)||!checkdate((int)$date[2],(int)$date[3],(int)$date[1])))fail(422,'Bitte ein gültiges Datum angeben.');
        $count=$s['userCount']??null;if($count!==null&&(!is_int($count)||$count<0||$count>100000000))fail(422,'Benutzeranzahl als nichtnegative ganze Zahl angeben.');$v['userCount']=$count;$out['systems'][]=$v;
    }
    foreach(labList($c['stores']??[],labLimits()['rows']) as $raw){$s=studioRecord($raw);$id=labName($s['id']??null);$s['system']=labName($s['system']??null);if(isset($stores[$id])||!isset($ids[$s['system']]))fail(422,'Datenbestände benötigen eine eindeutige ID und ein vorhandenes System.');$stores[$id]=$s['system'];$v=['id'=>$id,'system'=>$s['system'],'name'=>labName($s['name']??null,180),'classification'=>studioEnum($s['classification']??'unknown',['unknown','public','internal','confidential','restricted'])];foreach(['kind'=>180,'dataTypes'=>1500,'formats'=>500,'volume'=>500,'quality'=>1500,'purpose'=>1500,'retention'=>1000,'notes'=>2000] as $key=>$max)$v[$key]=studioText($s[$key]??'',$max);$out['stores'][]=$v;}
    $flows=[];foreach(labList($c['flows']??[],labLimits()['edges']) as $raw){$f=studioRecord($raw);$id=labName($f['id']??null);$f['from']=labName($f['from']??null);$f['to']=labName($f['to']??null);if(isset($flows[$id])||!isset($ids[$f['from']??''],$ids[$f['to']??''])||$f['from']===$f['to'])fail(422,'Datenflüsse benötigen zwei unterschiedliche vorhandene Systeme und eine eindeutige ID.');$flows[$id]=true;$v=['id'=>$id,'from'=>$f['from'],'to'=>$f['to'],'name'=>labName($f['name']??null,180),'direction'=>studioEnum($f['direction']??'forward',['forward','reverse','both']),'access'=>studioEnum($f['access']??'unknown',['unknown','read','write','readwrite']),'stores'=>labList($f['stores']??[],100),'criticality'=>studioEnum($f['criticality']??'unknown',['unknown','low','medium','high']),'basis'=>studioEnum($f['basis']??'assumption',['assumption','observed'])];foreach($v['stores'] as $sid)if(!is_string($sid)||!isset($stores[$sid])||!in_array($stores[$sid],$v['direction']==='both'?[$v['from'],$v['to']]:[$v['direction']==='reverse'?$v['to']:$v['from']],true))fail(422,'Übertragene Datenbestände müssen zu einem Quellsystem der gewählten Datenrichtung gehören.');if(count(array_unique($v['stores']))!==count($v['stores']))fail(422,'Datenbestand im Datenfluss doppelt gewählt.');foreach(['description'=>2000,'method'=>500,'frequency'=>500,'format'=>500,'volume'=>500,'security'=>1500,'owner'=>180,'evidence'=>2000] as $key=>$max)$v[$key]=studioText($f[$key]??'',$max);if($v['basis']==='observed'&&trim($v['evidence'])==='')fail(422,'Für dokumentierte Datenflüsse einen Beleg angeben.');$out['flows'][]=$v;}
    return $out;
}
function blueprintValidate(mixed $input,array $stages):array {
    $c=studioRecord($input);$stageIds=array_fill_keys(array_column($stages,'id'),true);$out=['items'=>[],'links'=>[]];$ids=[];
    foreach(labList($c['items']??[],300) as $raw){$i=studioRecord($raw);$id=labName($i['id']??null);$i['stage']=labName($i['stage']??null);if(isset($ids[$id])||!isset($stageIds[$i['stage']??'']))fail(422,'Blueprint-Aktivitäten benötigen eine eigene ID und eine vorhandene Journey-Phase.');$ids[$id]=true;$v=['id'=>$id,'stage'=>$i['stage'],'lane'=>studioEnum($i['lane']??null,['contact','frontstage','backstage','support']),'text'=>studioText($i['text']??'',2000),'basis'=>studioEnum($i['basis']??'assumption',['assumption','observed'])];if(trim($v['text'])==='')fail(422,'Eine Blueprint-Aktivität benötigt eine Beschreibung.');foreach(['owner'=>180,'systems'=>1000,'data'=>1000,'evidence'=>2000] as $key=>$max)$v[$key]=studioText($i[$key]??'',$max);$minutes=$i['minutes']??null;if($minutes!==null&&((!is_int($minutes)&&!is_float($minutes))||!is_finite((float)$minutes)||$minutes<0||$minutes>1000000))fail(422,'Dauer als nichtnegative Zahl in Minuten angeben.');$v['minutes']=$minutes;if($v['basis']==='observed'&&trim($v['evidence'])==='')fail(422,'Für beobachtete Aktivitäten einen Beleg angeben.');$out['items'][]=$v;}
    $linkIds=[];$pairs=[];foreach(labList($c['links']??[],600) as $raw){$l=studioRecord($raw);$id=labName($l['id']??null);$l['from']=labName($l['from']??null);$l['to']=labName($l['to']??null);if(isset($linkIds[$id])||!isset($ids[$l['from']??''],$ids[$l['to']??''])||$l['from']===$l['to'])fail(422,'Abhängigkeiten benötigen zwei unterschiedliche vorhandene Aktivitäten und eine eigene ID.');$pair=json_encode([$l['from'],$l['to']]);if(isset($pairs[$pair]))fail(422,'Diese Abhängigkeit besteht bereits.');$pairs[$pair]=true;$linkIds[$id]=true;$out['links'][]=['id'=>$id,'from'=>$l['from'],'to'=>$l['to'],'label'=>studioText($l['label']??'',180)];}
    return $out;
}
